//! Decides whether a clipboard change is stored. Pure functions, no I/O.
//!
//! Privacy design choice of Clipshelf: a change that carries any of the six
//! types below is skipped entirely and nothing from it is read or kept.
//! The list is the one found in a commercial clipboard manager; skipping on
//! match is our decision, not a copied behaviour.

use serde::Serialize;

/// Pasteboard types that mark content as transient, generated or secret.
pub const EXCLUDED_TYPES: [&str; 6] = [
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "org.nspasteboard.ConcealedType",
    "de.petermaurer.TransientPasteboardType",
    "com.typeit4me.clipping",
    "Pasteboard generated type",
];

/// Largest text we keep, in bytes.
pub const MAX_TEXT_BYTES: usize = 100_000;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum SkipReason {
    /// An excluded type is present. Nothing was read.
    ExcludedType,
    /// No plain text type is present, for example an image.
    NoText,
    /// A text type was listed but its contents could not be read.
    ReadFailed,
    /// Text is empty or only whitespace.
    Empty,
    /// Text is larger than `MAX_TEXT_BYTES`.
    TooLarge,
}

/// First excluded type present, if any. Exact string match.
pub fn excluded_type(types: &[String]) -> Option<&'static str> {
    EXCLUDED_TYPES
        .iter()
        .copied()
        .find(|excluded| types.iter().any(|t| t == excluded))
}

/// True when a plain text type is listed.
pub fn has_text_type(types: &[String]) -> bool {
    types
        .iter()
        .any(|t| t == "public.utf8-plain-text" || t == "NSStringPboardType")
}

/// Checks that depend on the text itself. Called only after the type check passed.
pub fn check_text(text: &str) -> Option<SkipReason> {
    if text.trim().is_empty() {
        Some(SkipReason::Empty)
    } else if text.len() > MAX_TEXT_BYTES {
        Some(SkipReason::TooLarge)
    } else {
        None
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn types(list: &[&str]) -> Vec<String> {
        list.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn each_of_the_six_types_is_excluded() {
        for excluded in EXCLUDED_TYPES {
            let t = types(&["public.utf8-plain-text", excluded]);
            assert_eq!(excluded_type(&t), Some(excluded));
        }
    }

    #[test]
    fn plain_text_alone_is_not_excluded() {
        assert_eq!(excluded_type(&types(&["public.utf8-plain-text"])), None);
    }

    #[test]
    fn similar_names_are_not_excluded() {
        assert_eq!(excluded_type(&types(&["org.nspasteboard.source"])), None);
        assert_eq!(
            excluded_type(&types(&["org.nspasteboard.concealedtype"])),
            None
        );
    }

    #[test]
    fn text_type_detection() {
        assert!(has_text_type(&types(&["public.utf8-plain-text"])));
        assert!(!has_text_type(&types(&["public.png"])));
    }

    #[test]
    fn text_checks() {
        assert_eq!(check_text("hello"), None);
        assert_eq!(check_text("   \n"), Some(SkipReason::Empty));
        assert_eq!(check_text(&"a".repeat(MAX_TEXT_BYTES)), None);
        assert_eq!(
            check_text(&"a".repeat(MAX_TEXT_BYTES + 1)),
            Some(SkipReason::TooLarge)
        );
    }
}
